with expected as (select year, body_type, make, generic_model, dense_rank() over(partition by year,body_type order by annual_registration_count desc) registration_rank from {{ ref('annual_model_registrations') }} where is_rank_eligible and year in ({{ var('ranking_years') | join(', ') }})), actual as (select year, body_type, make, generic_model, registration_rank from {{ ref('annual_model_rankings') }}) (select * from expected except all select * from actual) union all (select * from actual except all select * from expected)
